// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { AlertTriangleIcon, CheckIcon, CopyIcon, ShieldAlertIcon } from 'lucide-react'

import { DemoStage, PanelChrome, highlight, type Build } from '@/app/demos/stage'

import {
  ALG,
  CAPTIONS,
  EXPIRES,
  HEADER_JSON,
  NOT_VERIFIED,
  PARTS,
  PAYLOAD_JSON,
  STATUS,
  TOKEN,
  WARNINGS,
} from './script'

const TARGETS = ['header-pane', 'payload-pane', 'verify']

const build: Build = ({ tl, q, qa, step, final, move, click, fly, wait, cursorOut }) => {
  step(0)
  move('example', { at: 0.2 })
  click('example')
  tl.to(
    q('token-text'),
    { text: { value: TOKEN, delimiter: '' }, duration: 0.5, ease: 'none' },
    '<',
  )
  tl.fromTo(
    q('shine'),
    { xPercent: -120, opacity: 1 },
    { xPercent: 260, opacity: 1, duration: 0.9, ease: 'power2.inOut' },
    '>-0.1',
  )
  tl.set(q('shine'), { opacity: 0 })

  step(1, '+=0.3')
  PARTS.forEach((part, index) => {
    fly(`ghost-${part.name}`, 'token', TARGETS[index], {
      at: index === 0 ? '<' : '<0.15',
      duration: 0.9,
      lift: 40,
      scale: 0.9,
    })
  })
  tl.to(qa('ghost'), { opacity: 0, duration: 0.25, stagger: 0.15 }, '>-0.1')
  tl.fromTo(
    [q('header-pane'), q('payload-pane')],
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.15, ease: 'power2.out' },
    '<-0.2',
  )
  tl.fromTo(
    [...qa('header-line'), ...qa('payload-line')],
    { opacity: 0, x: -4 },
    { opacity: 1, x: 0, duration: 0.2, stagger: 0.04 },
    '<0.1',
  )

  step(2, '+=0.5')
  tl.fromTo(
    qa('badge'),
    { opacity: 0, scale: 0.6 },
    { opacity: 1, scale: 1, duration: 0.3, stagger: 0.1, ease: 'back.out(3)' },
  )
  tl.to(q('verify'), { opacity: 1, duration: 0.3 }, '<0.1')
  tl.fromTo(
    qa('warning'),
    { opacity: 0, y: 4 },
    { opacity: 1, y: 0, duration: 0.25, stagger: 0.12 },
    '<0.2',
  )

  step(3, '+=0.6')
  tl.fromTo(q('expires'), { opacity: 0, y: 4 }, { opacity: 1, y: 0, duration: 0.3 })
  move('copy-payload')
  click('copy-payload')
  tl.to(q('copy-payload'), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q('done-payload'),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
    '<',
  )
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

function Segment({ name, title, json }: { name: string; title: string; json: string }) {
  return (
    <div
      data-d={`${name}-pane`}
      className="min-w-0 rounded-md border border-line bg-white/[0.02] p-1.5 opacity-0"
    >
      <div className="mb-0.5 flex items-center justify-between">
        <span className="text-[10px] font-medium text-ink">{title}</span>
        <span className="relative size-3 text-muted">
          <span data-d={`copy-${name}`} className="absolute inset-0">
            <CopyIcon className="size-3" />
          </span>
          <span data-d={`done-${name}`} className="absolute inset-0 text-[var(--accent)] opacity-0">
            <CheckIcon className="size-3" />
          </span>
        </span>
      </div>
      <div className="font-mono text-[9px] leading-[13px] text-ink-soft">
        {json.split('\n').map((line, index) => (
          <div key={index} data-d={`${name}-line`} className="whitespace-pre">
            {highlight(line)}
          </div>
        ))}
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="JWT Toolkit splitting the example token into header, payload and signature, then showing its expiry status and claim warnings"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-1.5">
          <div
            data-d="token"
            className="relative h-[46px] overflow-hidden rounded-md border border-line-strong bg-canvas/80 px-2 py-1.5"
          >
            <p
              data-d="token-text"
              className="break-all font-mono text-[8.5px] leading-[11px] text-ink-soft empty:before:text-muted empty:before:content-['Paste_a_JWT…']"
            />
            <span
              data-d="shine"
              className="pointer-events-none absolute inset-y-0 left-0 w-1/3 bg-[linear-gradient(100deg,transparent,rgba(251,113,133,0.25),rgba(167,139,250,0.3),rgba(34,211,238,0.25),transparent)] opacity-0"
            />
          </div>
          <span data-d="example" className="w-fit text-[10px] text-[var(--accent)]">
            Try example
          </span>
          <div className="flex items-center gap-1.5">
            <span
              data-d="badge"
              className="rounded-full border border-emerald/40 px-2 py-0.5 text-[9.5px] text-emerald opacity-0"
            >
              {STATUS}
            </span>
            <span
              data-d="badge"
              className="rounded-full border border-line-strong px-2 py-0.5 text-[9.5px] text-ink-soft opacity-0"
            >
              {ALG}
            </span>
          </div>
          <div
            data-d="verify"
            className="flex items-start gap-1.5 rounded-md border border-amber/40 bg-amber/5 px-2 py-1 text-[9.5px] leading-snug text-amber opacity-0"
          >
            <ShieldAlertIcon className="mt-px size-3 shrink-0" />
            {NOT_VERIFIED}
          </div>
          <div className="space-y-0.5">
            {WARNINGS.map((warning) => (
              <p
                key={warning}
                data-d="warning"
                className="flex items-start gap-1.5 text-[9.5px] text-amber opacity-0"
              >
                <AlertTriangleIcon className="mt-px size-2.5 shrink-0" /> {warning}
              </p>
            ))}
          </div>
          <div className="grid grid-cols-[0.8fr_1.2fr] gap-1.5">
            <Segment name="header" title="Header" json={HEADER_JSON} />
            <Segment name="payload" title="Payload" json={PAYLOAD_JSON} />
          </div>
          <p data-d="expires" className="text-[9.5px] text-muted opacity-0">
            Expires: {EXPIRES}
          </p>
        </div>
      </PanelChrome>
      {PARTS.map((part) => (
        <span
          key={part.name}
          data-d={`ghost ghost-${part.name}`}
          className="absolute left-0 top-0 z-20 max-w-[130px] truncate rounded-md border px-1.5 py-0.5 font-mono text-[9px] opacity-0 shadow-lg backdrop-blur"
          style={{
            color: part.color,
            borderColor: `${part.color}80`,
            backgroundColor: `${part.color}1f`,
          }}
        >
          {part.value}
        </span>
      ))}
    </DemoStage>
  )
}
